import java.util.*;

public class Main {
    public static void main(String[] args) {
        System.out.println(Integer.MAX_VALUE + 1);
        int lo = 1_500_000_000, hi = 2_000_000_000;
        System.out.println("(lo+hi)/2 = " + (lo + hi) / 2 + "  lo+(hi-lo)/2 = " + (lo
                + (hi - lo) / 2));
        int big = 100_000;
        System.out.println(big * big + " " + (long) big * big + " " + 1L * big * big);
        try { Math.multiplyExact(big, big); } catch (ArithmeticException e)
                { System.out.println(e.getMessage()); }
        System.out.println(Math.abs(Integer.MIN_VALUE) + " " + (-Integer.MIN_VALUE));
        System.out.println(-7 / 2 + " " + -7 % 2 + " " + Math.floorMod(-7, 2) + " " + (7 >> 1)
                + " " + (-7 >>> 28));
        Integer[] arr = {Integer.MIN_VALUE, 1};
        Arrays.sort(arr, (x, y) -> x - y);
        System.out.println("a-b comparator: " + Arrays.toString(arr));
        Arrays.sort(arr, Integer::compare);
        System.out.println("Integer.compare: " + Arrays.toString(arr));
        Integer p = 127, q = 127, r = 128, u = 128;
        System.out.println((p == q) + " " + (r == u) + " " + r.equals(u));
        List<Integer> list = new ArrayList<>(List.of(10, 20, 30, 1));
        list.remove(1);
        System.out.println(list);
        list.remove(Integer.valueOf(1));
        System.out.println(list);
        try { List.of(1).add(2); } catch (UnsupportedOperationException e)
                { System.out.println("List.of is immutable"); }
        long sum = 0;
        for (int i = 0; i < 100_000; i++) sum += i;
        int wrong = 0;
        for (int i = 0; i < 100_000; i++) wrong += i;
        System.out.println(sum + " vs int " + wrong);
        System.out.println(Long.MAX_VALUE + " " + Integer.MAX_VALUE + " " + (char) ('a' + 1)
                + " " + ('a' + 1));
        System.out.println(Integer.bitCount(255) + " " + Integer.toBinaryString(10) + " "
                + Long.numberOfTrailingZeros(8));
        System.out.println((0.1 + 0.2) + " " + (0.1 + 0.2 == 0.3) + " " + (5 / 2) + " "
                + (5 / 2.0));
    }
}

import java.util.*;

public class Main {
    record Pair(int a, int b) {}
    record Job(String name, int prio, int time) {}

    public static void main(String[] args) {
        Map<Character, Integer> cnt = new HashMap<>();
        for (char ch : "banana".toCharArray()) cnt.merge(ch, 1, Integer::sum);
        System.out.println(cnt);
        Map<Integer, List<String>> byLen = new TreeMap<>();
        for (String w : List.of("hi", "yo", "hey", "a")) byLen.computeIfAbsent(w.length(),
                k -> new ArrayList<>()).add(w);
        System.out.println(byLen + " " + cnt.getOrDefault('z', 0));
        TreeMap<Integer, String> tm = new TreeMap<>(Map.of(10, "a", 20, "b", 30, "c"));
        System.out.println(tm.floorKey(25) + " " + tm.ceilingKey(25) + " " + tm.lowerKey(10) + " "
                + tm.firstKey() + " " + tm.lastEntry() + " " + tm.headMap(30));
        TreeSet<Integer> ts = new TreeSet<>(List.of(5, 1, 9));
        System.out.println(ts + " " + ts.higher(5) + " " + ts.pollFirst() + " "
                + ts.descendingSet());
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(1); stack.push(2); stack.push(3);
        System.out.println("stack " + stack + " peek=" + stack.peek() + " pop=" + stack.pop());
        Deque<Integer> queue = new ArrayDeque<>();
        queue.offer(1); queue.offer(2); queue.offer(3);
        System.out.println("queue " + queue + " poll=" + queue.poll() + " peekLast="
                + queue.peekLast());
        PriorityQueue<Integer> minH = new PriorityQueue<>(List.of(5, 1, 8, 3));
        PriorityQueue<Integer> maxH = new PriorityQueue<>(Comparator.reverseOrder());
        maxH.addAll(List.of(5, 1, 8, 3));
        System.out.println(minH.poll() + " " + maxH.poll() + " size=" + minH.size());
        PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> Integer.compare(x[1], y[1]));
        pq.add(new int[]{0, 9}); pq.add(new int[]{1, 4}); pq.add(new int[]{2, 6});
        System.out.println(Arrays.toString(pq.poll()));
        List<Job> jobs = new ArrayList<>(List.of(new Job("a", 2, 30), new Job("b", 1, 50),
                new Job("c", 2, 10)));
        jobs.sort(Comparator.comparingInt(Job::prio).thenComparing(Job::time,
                Comparator.reverseOrder()));
        System.out.println(jobs);
        Set<Pair> seen = new HashSet<>();
        System.out.println(seen.add(new Pair(1, 2)) + " " + seen.add(new Pair(1, 2)) + " "
                + new Pair(3, 4));
        List<Integer> nums = new ArrayList<>(List.of(1, 2, 3, 4));
        Collections.reverse(nums); Collections.swap(nums, 0, 3);
        System.out.println(nums + " max=" + Collections.max(nums) + " "
                + Collections.frequency(nums, 2));
        @SuppressWarnings("unchecked")
        List<Integer>[] graph = new List[3];
        for (int i = 0; i < 3; i++) graph[i] = new ArrayList<>();
        graph[0].add(1); graph[0].add(2); graph[1].add(2);
        System.out.println(Arrays.toString(graph));
        int[][] jag = new int[3][];
        for (int i = 0; i < 3; i++) jag[i] = new int[i + 1];
        System.out.println(Arrays.deepToString(jag) + " rows=" + jag.length + " cols0="
                + jag[0].length);
        int[][] g = {{1, 2}, {3, 4}};
        int[][] shallow = g.clone();
        shallow[0][0] = 99;
        System.out.println(g[0][0]);
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int cnt2 = 0;
        for (int[] d : dirs) { int nr = 0 + d[0], nc = 0 + d[1]; if (nr >= 0 && nc >= 0) cnt2++; }
        System.out.println("neighbours of (0,0) in bounds: " + cnt2);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int depth = 0;
    static void down() { depth++; down(); }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        long total = 0;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) { a[i] = Integer.parseInt(st.nextToken()); total += a[i]; }
        StringBuilder out = new StringBuilder();
        out.append(total).append('\n').append(Arrays.toString(a));
        System.out.println(out);
        try { down(); } catch (StackOverflowError e) { System.out.println("depth > 1000: "
                + (depth > 1000)); }
        System.out.println("depth reached (typical): " + depth);
    }
}
